# Collection of small helpers.

def identity(x):
    return x

def add_one(x):
    return x + 1

def add_two(x):
    return x + 2

def double(x):
    return x * 2

def triple(x):
    return x * 3

def is_even(x):
    return x % 2 == 0

def is_odd(x):
    return x % 2 == 1

def square(x):
    return x * x

def cube(x):
    return x ** 3

def clamp(x, lo, hi):
    return max(lo, min(hi, x))

def abs_value(x):
    return abs(x)

def sign(x):
    if x > 0:
        return 1
    if x < 0:
        return -1
    return 0

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def factorial(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def reverse_string(s):
    return s[::-1]

def count_vowels(s):
    return sum(1 for c in s.lower() if c in "aeiou")
